class Solution:
    def convert(self, s: str, numRows: int) -> str:
        if numRows==1: return s
        rows=['']*numRows
        r,d=0,1
        for c in s:
            rows[r]+=c
            if r==0: d=1
            elif r==numRows-1: d=-1
            r+=d
        return ''.join(rows)

class Solution:
    def findSubstring(self, s, words):
        from collections import Counter
        if not words: return []
        wl,n,m=len(words[0]),len(s),len(words)
        need=Counter(words)
        res=[]
        for i in range(wl):
            l=i; cur=Counter(); cnt=0
            for r in range(i,n-wl+1,wl):
                w=s[r:r+wl]
                if w in need:
                    cur[w]+=1; cnt+=1
                    while cur[w]>need[w]:
                        cur[s[l:l+wl]]-=1; l+=wl; cnt-=1
                    if cnt==m: res.append(l)
                else:
                    cur.clear(); cnt=0; l=r+wl
        return res

class Solution:
    def isNumber(self, s: str) -> bool:
        import re
        return bool(re.match(r'^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$', s.strip()))

class Solution:
    def fullJustify(self, words, maxWidth):
        res,line,length=[],[],0
        for w in words:
            if length+len(w)+len(line)>maxWidth:
                for i in range(maxWidth-length):
                    line[i%(len(line)-1 or 1)]+=' '
                res.append(''.join(line))
                line,length=[],0
            line.append(w); length+=len(w)
        res.append(' '.join(line).ljust(maxWidth))
        return res

