class Solution:
    def cutOffTree(self, forest):
        from collections import deque
        trees=sorted((h,i,j) for i,r in enumerate(forest) for j,h in enumerate(r) if h>1)
        def bfs(sr,sc,tr,tc):
            q=deque([(sr,sc,0)]); seen={(sr,sc)}
            while q:
                r,c,d=q.popleft()
                if r==tr and c==tc: return d
                for nr,nc in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
                    if 0<=nr<len(forest) and 0<=nc<len(forest[0]) and (nr,nc) not in seen and forest[nr][nc]:
                        seen.add((nr,nc)); q.append((nr,nc,d+1))
            return -1
        sr=sc=0; total=0
        for _,tr,tc in trees:
            d=bfs(sr,sc,tr,tc)
            if d<0: return -1
            total+=d; sr,sc=tr,tc
        return total

class Solution:
    def numDistinctIslands2(self, grid) -> int:
        from collections import deque
        m,n=len(grid),len(grid[0])
        def bfs(i,j):
            q=deque([(i,j)]); grid[i][j]=0; cells=[(i,j)]
            while q:
                r,c=q.popleft()
                for nr,nc in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
                    if 0<=nr<m and 0<=nc<n and grid[nr][nc]:
                        grid[nr][nc]=0; q.append((nr,nc)); cells.append((nr,nc))
            return cells
        def normalize(cells):
            shapes=[]
            for fn in [lambda r,c:(r,c),lambda r,c:(r,-c),lambda r,c:(-r,c),lambda r,c:(-r,-c),lambda r,c:(c,r),lambda r,c:(c,-r),lambda r,c:(-c,r),lambda r,c:(-c,-r)]:
                t=sorted(fn(r,c) for r,c in cells)
                t=[(r-t[0][0],c-t[0][1]) for r,c in t]
                shapes.append(tuple(t))
            return min(shapes)
        seen=set()
        for i in range(m):
            for j in range(n):
                if grid[i][j]:
                    cells=bfs(i,j)
                    seen.add(normalize(cells))
        return len(seen)

class Solution:
    def isRationalEqual(self, s: str, t: str) -> bool:
        def val(s):
            if '(' not in s: return float(s)
            i=s.index('('); rep=s[i+1:-1]
            return float(s[:i]+rep*20)
        return abs(val(s)-val(t))<1e-9
